/** Settings screen renderer (Tier 5, ADR-0207 follow-up + Tier 7 quota UI).
 *
 * Audio controls panel: BGM volume + SFX volume sliders + global mute toggle.
 * Language toggle (EN/KO) — persisted via localStorage. Drives the language
 * arg of the menu + Far Grid hub renderers (which already accept `language`).
 * Storage quota panel: IDB usage bar + percent + warning levels.
 * Volumes are persisted via AudioManager (localStorage). The renderer is
 * pure: it reads current values from the AudioManager instance and emits
 * a Grid; the main game loop handles input dispatch (Left/Right to
 * decrement/increment, M to toggle mute, ESC to back out).
 */
import type { Grid } from "../core/types";
import { makeGrid, setText } from "../core/grid";
import { PALETTE } from "./palette";
import {
  drawPanel,
  panelInnerRect,
  screenFrameRect,
  setInnerText,
  type PanelRect,
} from "./panel";
import { AudioManager } from "../audio/manager";
import {
  getStorageQuota,
  renderUsageBar,
  quotaLevel,
  summarizeQuota,
  type StorageQuota,
} from "../save/storage_quota";
import { isLanguageSupported, t, type Language } from "../core/i18n";
import { INITIAL_PWA_STATE, type PwaState } from "../core/pwa_manager";
import {
  loadColorblindMode,
  loadHighContrastOverride,
  loadReducedMotionOverride,
  loadTextScale,
  resolveHighContrast,
  resolveReducedMotion,
  type ColorblindMode,
  type TextScaleStep,
} from "./accessibility_modes";

/** Default `pwa` slot for callers that don't have a live controller. */
export function defaultPwaState(): PwaState {
  return INITIAL_PWA_STATE;
}

/** localStorage key for the persisted UI language (EN/KO).
 *
 * Mirrors the `wetrun_*` key convention used by audio settings
 * (`wetrun_audio_off`, `wetrun_audio_bgm_volume`, …) and other persisted
 * toggles. Stored value is the bare language code ("en" or "ko"). Unknown
 * or malformed values are rejected at read time — see `loadPersistedLanguage`.
 */
export const LANGUAGE_STORAGE_KEY = "wetrun_language";

/** Read the persisted UI language. Returns "en" when missing/invalid. */
export function loadPersistedLanguage(): Language {
  if (typeof localStorage === "undefined") return "en";
  const raw = localStorage.getItem(LANGUAGE_STORAGE_KEY);
  if (raw !== null && isLanguageSupported(raw)) return raw;
  return "en";
}

/** Persist the UI language. No-op when localStorage is unavailable. */
export function persistLanguage(language: Language): void {
  if (typeof localStorage === "undefined") return;
  localStorage.setItem(LANGUAGE_STORAGE_KEY, language);
}

/** Cycle the language to the next supported value (en → ko → en). */
export function cycleLanguage(current: Language): Language {
  return current === "en" ? "ko" : "en";
}

export type SettingsField =
  | "audio"
  | "master"
  | "bgm"
  | "sfx"
  | "mute"
  | "language"
  | "pwa_install"
  | "pwa_update"
  | "reduced_motion"
  | "high_contrast"
  | "colorblind"
  | "text_scale";

export interface SettingsState {
  selectedField: SettingsField;
  audioEnabled: boolean;
  /** Master volume (0..1) — multiplies BGM and SFX. Optional because
   * `main.ts` still constructs this shape without it; the renderer treats
   * `undefined` as 1. */
  masterVolume?: number;
  bgmVolume: number;
  sfxVolume: number;
  muted: boolean;
  language: Language;
  storageQuota: StorageQuota;
  /** Live PWA state — populated by `bootPwaController` in main.ts. */
  pwa: PwaState;
  /** P10 — effective reduced-motion state (override resolved against the
   * OS media query). */
  reducedMotion?: boolean;
  /** P10 — effective high-contrast state (override resolved against the
   * OS `prefers-contrast` media query). */
  highContrast?: boolean;
  /** P10 — the 4-mode colorblind palette selection (ADR-0196). */
  colorblindMode?: ColorblindMode;
  /** P10 — the text-scale step. */
  textScale?: TextScaleStep;
}

const VOLUME_STEP = 0.1;

/**
 * Synchronous version — uses an unavailable quota placeholder.
 * Use `getInitialSettingsStateAsync` from main.ts to fetch real quota.
 *
 * Pass an optional `pwa` snapshot from `bootPwaController().state` so the
 * PWA section reflects live install/update/offline status instead of
 * `INITIAL_PWA_STATE`.
 */
export function getInitialSettingsState(
  pwa: PwaState = defaultPwaState(),
): SettingsState {
  const language = loadPersistedLanguage();
  const accessibility = accessibilitySettings();
  let audio: AudioManager;
  try {
    audio = AudioManager.getInstance();
  } catch {
    return {
      selectedField: "audio",
      audioEnabled: localStorage.getItem("wetrun_audio_off") !== "1",
      masterVolume: 1,
      bgmVolume: 0.4,
      sfxVolume: 0.6,
      muted: false,
      language,
      storageQuota: { state: "unavailable", reason: "not yet fetched" },
      pwa,
      ...accessibility,
    };
  }
  return {
    selectedField: "audio",
    audioEnabled: !audio.isMuted(),
    masterVolume: audio.getMasterVolume(),
    bgmVolume: audio.getBgmVolume(),
    sfxVolume: audio.getSfxVolume(),
    muted: audio.isMuted(),
    language,
    storageQuota: { state: "unavailable", reason: "not yet fetched" },
    pwa,
    ...accessibility,
  };
}

/** The P10 accessibility slice of the settings state, read from storage. */
function accessibilitySettings(): {
  readonly reducedMotion: boolean;
  readonly highContrast: boolean;
  readonly colorblindMode: ColorblindMode;
  readonly textScale: TextScaleStep;
} {
  return {
    reducedMotion: resolveReducedMotion(loadReducedMotionOverride()),
    highContrast: resolveHighContrast(loadHighContrastOverride()),
    colorblindMode: loadColorblindMode(),
    textScale: loadTextScale(),
  };
}

/**
 * Async version that fetches the live storage quota via navigator.storage.estimate().
 * Returns a fully-populated SettingsState with real IDB usage stats.
 *
 * Pass the live `pwa` snapshot so the PWA section reflects install/update/offline.
 */
export async function getInitialSettingsStateAsync(
  pwa: PwaState = defaultPwaState(),
): Promise<SettingsState> {
  const audio = AudioManager.getInstance();
  const storageQuota = await getStorageQuota();
  return {
    selectedField: "audio",
    audioEnabled: !audio.isMuted(),
    masterVolume: audio.getMasterVolume(),
    bgmVolume: audio.getBgmVolume(),
    sfxVolume: audio.getSfxVolume(),
    muted: audio.isMuted(),
    language: loadPersistedLanguage(),
    storageQuota,
    pwa,
    ...accessibilitySettings(),
  };
}

export function clampVolume(v: number): number {
  if (Number.isNaN(v)) return 0;
  if (v < 0) return 0;
  if (v > 1) return 1;
  return v;
}

export function adjustVolume(v: number, direction: "inc" | "dec"): number {
  const delta = direction === "inc" ? VOLUME_STEP : -VOLUME_STEP;
  return clampVolume(Math.round((v + delta) * 10) / 10);
}

/** Where the settings screen places its content inside the inset frame. */
export interface SettingsLayout {
  readonly frame: PanelRect;
  readonly inner: PanelRect;
  /** First of the two footer rows (controls hint, then persistence note). */
  readonly footerY: number;
  /** Header spacer offsets (from `HEADER_SPACERS`) dropped to fit a short
   * grid; empty on every preset of 43 rows or more. */
  readonly collapsedSpacers: readonly number[];
}

/** Frame-relative offset of the last body row (the online/offline line). */
const BODY_LAST_OFFSET = 37;

/** Blank rows between a section header and its first item (AUDIO, LANGUAGE,
 * PWA), in the order they are given up when the grid is short — bottom first.
 * ACCESSIBILITY and STORAGE already have no such spacer, so dropping these
 * only makes the sections uniform; no item is dropped or reordered.
 */
const HEADER_SPACERS: readonly number[] = [34, 21, 6];

/** The original fixed rows and columns, translated into the inset frame.
 *
 * Every body offset keeps the distance from the frame's top-left corner that
 * it used to have from the grid's (a +1/+1 parallel move). Footer rule
 * (ADR-0237 Open question (f)): the two-line footer is pinned to the last two
 * INNER rows only when the body ends above them; otherwise it follows the
 * body's last row in flow. To keep that flow inside the frame on the 60x40
 * preset (36 inner rows for a 37-row body + 2-row footer), up to three header
 * spacers collapse — exactly as many as the overflow needs, bottom first.
 * Grids of 43+ rows collapse nothing and keep the pinned footer. Grids under
 * 40 rows (no real preset) cannot hold everything even collapsed; they keep
 * the pre-fix layout, where the pinned controls hint wins over the body.
 */
export function settingsLayout(cols: number, rows: number): SettingsLayout {
  const frame = screenFrameRect({ width: cols, height: rows });
  const inner = panelInnerRect(makeGrid(cols, rows), frame);
  const pinnedY = inner.y + inner.height - 2;
  const overflow = Math.max(0, frame.y + BODY_LAST_OFFSET + 1 - pinnedY);
  if (overflow > HEADER_SPACERS.length) {
    return { frame, inner, footerY: pinnedY, collapsedSpacers: [] };
  }
  const collapsedSpacers = HEADER_SPACERS.slice(0, overflow);
  const bodyEnd = frame.y + BODY_LAST_OFFSET - collapsedSpacers.length;
  const footerY = bodyEnd < pinnedY ? pinnedY : bodyEnd + 1;
  return { frame, inner, footerY, collapsedSpacers };
}

/** Absolute grid row of a frame-relative body offset under `layout`. */
function bodyRow(layout: SettingsLayout, offset: number): number {
  const shift = layout.collapsedSpacers.filter((s) => s < offset).length;
  return layout.frame.y + offset - shift;
}

/** Writes text at an original grid-origin offset, re-measured from the frame. */
type FramedWriter = (
  grid: Grid,
  x: number,
  y: number,
  text: string,
  fg: string,
) => Grid;

function renderSlider(
  grid: Grid,
  at: FramedWriter,
  label: string,
  value: number,
  selected: boolean,
  row: number,
): Grid {
  const labelFg = selected ? PALETTE.YELLOW_AMBER : PALETTE.GRAY_LIGHT;
  const width = 20;
  const filledCells = Math.round(value * width);
  const bar = "█".repeat(filledCells) + "░".repeat(width - filledCells);
  const percent = Math.round(value * 100)
    .toString()
    .padStart(3, " ");
  let out = at(grid, 4, row, label, labelFg);
  out = at(
    out,
    4,
    row + 1,
    `[${bar}] ${percent}%`,
    selected ? PALETTE.GREEN_NEON : PALETTE.GRAY_MID,
  );
  return out;
}

/** Render the settings screen inside the inset Green Grid frame (ADR-0237 §2).
 * Items, order, values and colours are unchanged; every line goes through
 * `setInnerText` and the frame is drawn last so no line can erase a rail.
 */
export function renderSettingsScreen(
  state: SettingsState,
  cols: number,
  rows: number,
): Grid {
  let grid = makeGrid(cols, rows);
  const layout = settingsLayout(cols, rows);
  const { frame, inner } = layout;
  const at: FramedWriter = (g, x, y, text, fg) =>
    setInnerText(g, inner, frame.x + x, bodyRow(layout, y), text, fg);

  grid = at(
    grid,
    Math.max(2, Math.floor((cols - 14) / 2)),
    1,
    "WET RUN — Settings",
    PALETTE.GREEN_NEON,
  );
  grid = at(grid, 2, 3, "─".repeat(Math.min(cols - 4, 50)), PALETTE.GRAY_MID);

  const audioLabel = state.audioEnabled
    ? "[X] AUDIO ENABLED"
    : "[ ] AUDIO ENABLED";
  const audioFg =
    state.selectedField === "audio"
      ? PALETTE.YELLOW_AMBER
      : state.audioEnabled
        ? PALETTE.GREEN_NEON
        : PALETTE.RED_BRIGHT;
  grid = at(grid, 4, 5, "AUDIO", PALETTE.CYAN_LIGHT);
  grid = at(grid, 4, 7, audioLabel, audioFg);

  grid = renderSlider(
    grid,
    at,
    "Master Volume",
    state.masterVolume ?? 1,
    state.selectedField === "master",
    9,
  );

  grid = renderSlider(
    grid,
    at,
    "BGM Volume",
    state.bgmVolume,
    state.selectedField === "bgm",
    12,
  );

  grid = renderSlider(
    grid,
    at,
    "SFX Volume",
    state.sfxVolume,
    state.selectedField === "sfx",
    15,
  );

  const muteLabel = state.muted ? "[X] MUTE ALL" : "[ ] MUTE ALL";
  const muteFg =
    state.selectedField === "mute"
      ? PALETTE.YELLOW_AMBER
      : state.muted
        ? PALETTE.RED_BRIGHT
        : PALETTE.GRAY_LIGHT;
  grid = at(grid, 4, 18, muteLabel, muteFg);

  grid = at(
    grid,
    4,
    20,
    t("settings.language", state.language),
    PALETTE.CYAN_LIGHT,
  );
  const languageLabel = state.language === "ko" ? "[X] KO" : "[ ] EN";
  const languageFg =
    state.selectedField === "language"
      ? PALETTE.YELLOW_AMBER
      : state.language === "ko"
        ? PALETTE.GREEN_NEON
        : PALETTE.GRAY_LIGHT;
  grid = at(grid, 4, 22, languageLabel, languageFg);

  // P10 — ACCESSIBILITY section (reduced motion / high contrast / colorblind
  // palette / text scale). Rows 24-28; the STORAGE and PWA sections below
  // were shifted down by 5 rows to make room. In a grid shorter than 29 rows
  // these rows are clipped — nothing existing is overwritten.
  grid = at(grid, 4, 24, "ACCESSIBILITY", PALETTE.CYAN_LIGHT);

  const reducedMotion = state.reducedMotion ?? false;
  const reducedLabel = reducedMotion
    ? "[X] REDUCED MOTION"
    : "[ ] REDUCED MOTION";
  grid = at(
    grid,
    4,
    25,
    reducedLabel,
    state.selectedField === "reduced_motion"
      ? PALETTE.YELLOW_AMBER
      : reducedMotion
        ? PALETTE.GREEN_NEON
        : PALETTE.GRAY_LIGHT,
  );

  const highContrast = state.highContrast ?? false;
  const contrastLabel = highContrast
    ? "[X] HIGH CONTRAST"
    : "[ ] HIGH CONTRAST";
  grid = at(
    grid,
    4,
    26,
    contrastLabel,
    state.selectedField === "high_contrast"
      ? PALETTE.YELLOW_AMBER
      : highContrast
        ? PALETTE.GREEN_NEON
        : PALETTE.GRAY_LIGHT,
  );

  const colorblindMode = state.colorblindMode ?? "none";
  const colorblindLabel = `[ ] COLORBLIND: ${colorblindMode.toUpperCase()}`;
  grid = at(
    grid,
    4,
    27,
    colorblindLabel,
    state.selectedField === "colorblind"
      ? PALETTE.YELLOW_AMBER
      : colorblindMode === "none"
        ? PALETTE.GRAY_LIGHT
        : PALETTE.GREEN_NEON,
  );

  const textScale = state.textScale ?? "medium";
  const textScaleLabel = `[ ] TEXT SCALE: ${textScale.toUpperCase()}`;
  grid = at(
    grid,
    4,
    28,
    textScaleLabel,
    state.selectedField === "text_scale"
      ? PALETTE.YELLOW_AMBER
      : textScale === "medium"
        ? PALETTE.GRAY_LIGHT
        : PALETTE.GREEN_NEON,
  );

  grid = at(grid, 4, 30, "STORAGE", PALETTE.CYAN_LIGHT);
  if (state.storageQuota.state === "unavailable") {
    grid = at(grid, 4, 31, `[ Storage API unavailable ]`, PALETTE.GRAY_DARK);
  } else {
    const level = quotaLevel(state.storageQuota.percent);
    const barColor =
      level === "critical"
        ? PALETTE.RED_BRIGHT
        : level === "warning"
          ? PALETTE.YELLOW_AMBER
          : PALETTE.GREEN_NEON;
    const bar = renderUsageBar(state.storageQuota.percent, 20);
    grid = at(grid, 4, 31, `[${bar}] ${state.storageQuota.percent}%`, barColor);
  }

  // PWA section: install row, update row, offline status line.
  // Always rendered (uses live `state.pwa` from bootPwaController) — never
  // hidden, so the player can always see the current status.
  grid = at(grid, 4, 33, t("settings.pwa", state.language), PALETTE.CYAN_LIGHT);

  const pwa = state.pwa;
  // Install row: [ ] when not installable, [X] INSTALLED when standalone,
  // [ ] INSTALL APP otherwise (will be selectable only when canInstall).
  let installLabel: string;
  let installFg: string;
  if (pwa.isInstalled) {
    installLabel = `[X] ${t("settings.pwa_installed", state.language)}`;
    installFg = PALETTE.GREEN_NEON;
  } else if (pwa.canInstall) {
    installLabel = `[ ] ${t("settings.pwa_install", state.language)}`;
    installFg =
      state.selectedField === "pwa_install"
        ? PALETTE.YELLOW_AMBER
        : PALETTE.GRAY_LIGHT;
  } else {
    installLabel = `[ ] ${t("settings.pwa_unavailable", state.language)}`;
    installFg =
      state.selectedField === "pwa_install"
        ? PALETTE.YELLOW_AMBER
        : PALETTE.GRAY_DARK;
  }
  grid = at(grid, 4, 35, installLabel, installFg);

  // Update row: lights up when the controller has detected a waiting worker
  // or a `controllerchange` event fired.
  const updateLabel = pwa.hasUpdate
    ? `[X] ${t("settings.pwa_update_available", state.language)}`
    : `[ ] ${t("settings.pwa_update", state.language)}`;
  const updateFg =
    state.selectedField === "pwa_update"
      ? PALETTE.YELLOW_AMBER
      : pwa.hasUpdate
        ? PALETTE.GREEN_NEON
        : PALETTE.GRAY_LIGHT;
  grid = at(grid, 4, 36, updateLabel, updateFg);

  // Offline status line (informational only — not selectable).
  const offlineLabel = pwa.isOffline
    ? t("settings.pwa_offline", state.language)
    : t("settings.pwa_online", state.language);
  const offlineFg = pwa.isOffline ? PALETTE.YELLOW_AMBER : PALETTE.GRAY_DARK;
  grid = at(grid, 4, 37, offlineLabel, offlineFg);

  const hint =
    state.selectedField === "audio"
      ? "ENTER: toggle audio | TAB: switch | ESC: back"
      : state.selectedField === "mute"
        ? "ENTER: toggle mute | TAB: switch | ESC: back"
        : state.selectedField === "language"
          ? "ENTER: toggle language | TAB: switch | ESC: back"
          : state.selectedField === "pwa_install"
            ? "ENTER: install app | ESC: back"
            : state.selectedField === "pwa_update"
              ? "ENTER: apply update | ESC: back"
              : state.selectedField === "reduced_motion"
                ? "ENTER: toggle reduced motion | TAB: switch | ESC: back"
                : state.selectedField === "high_contrast"
                  ? "ENTER: toggle high contrast | TAB: switch | ESC: back"
                  : state.selectedField === "colorblind"
                    ? "ENTER: cycle colorblind mode | TAB: switch | ESC: back"
                    : state.selectedField === "text_scale"
                      ? "ENTER: cycle text scale | TAB: switch | ESC: back"
                      : "←/→: adjust volume | TAB: switch | ESC: back";
  const footerX = frame.x + 2;
  grid = setInnerText(
    grid,
    inner,
    footerX,
    layout.footerY,
    hint,
    PALETTE.GRAY_DARK,
  );
  grid = setInnerText(
    grid,
    inner,
    footerX,
    layout.footerY + 1,
    "Volumes persist via localStorage",
    PALETTE.GRAY_DARK,
  );

  // Frame last, so an overlong line can never erase a rail.
  return drawPanel(grid, frame).grid;
}

/**
 * Render the storage quota section: label + usage bar + percent + warning hint.
 * Tier 7 — gives the player visibility into IDB usage before hitting quota.
 */
export function renderStorageQuota(
  grid: Grid,
  quota: StorageQuota,
  cols: number,
  row: number,
): Grid {
  let out = setText(grid, 4, row, "STORAGE", PALETTE.CYAN_LIGHT);
  if (quota.state === "unavailable") {
    out = setText(
      out,
      4,
      row + 1,
      `[ Storage API unavailable ]`,
      PALETTE.GRAY_DARK,
    );
    out = setText(
      out,
      4,
      row + 2,
      quota.reason.slice(0, Math.max(0, cols - 6)),
      PALETTE.GRAY_DARK,
    );
    return out;
  }
  const level = quotaLevel(quota.percent);
  const barColor =
    level === "critical"
      ? PALETTE.RED_BRIGHT
      : level === "warning"
        ? PALETTE.YELLOW_AMBER
        : PALETTE.GREEN_NEON;
  const bar = renderUsageBar(quota.percent, 20);
  const summary = summarizeQuota(quota);
  out = setText(out, 4, row + 1, `[${bar}] ${quota.percent}%`, barColor);
  out = setText(out, 4, row + 2, summary, barColor);
  if (level === "warning") {
    out = setText(
      out,
      4,
      row + 3,
      "! Storage filling up — clear old saves",
      PALETTE.YELLOW_AMBER,
    );
  } else if (level === "critical") {
    out = setText(
      out,
      4,
      row + 3,
      "!! Quota nearly full — save may fail",
      PALETTE.RED_BRIGHT,
    );
  }
  return out;
}

/** Async getter for quota re-fetch (called when user revisits Settings). */
export async function refreshStorageQuota(): Promise<StorageQuota> {
  return getStorageQuota();
}
